<template><div class="app-container"><el-card><template #header>交期检查</template><el-form :model="form" :inline="true"><el-form-item label="产品编码"><el-input v-model="form.productCode" placeholder="请输入产品编码" /></el-form-item><el-form-item label="数量"><el-input-number v-model="form.quantity" :min="1" /></el-form-item><el-form-item><el-button type="primary" @click="handleCheck">检查交期</el-button></el-form-item></el-form><el-divider /><el-descriptions v-if="result" title="交期结果" border><el-descriptions-item label="可承诺交期">{{result.atpDate}}</el-descriptions-item><el-descriptions-item label="可承诺数量">{{result.atpQuantity}}</el-descriptions-item><el-descriptions-item label="最早交付">{{result.earliestDate}}</el-descriptions-item></el-descriptions></el-card></div></template>
<script setup lang="ts">import { ref, reactive } from 'vue';import { checkAtp } from '@/api/cpq/atp';import { ElMessage } from 'element-plus';const form=reactive({productCode:'',quantity:1});const result=ref<any>(null);const handleCheck=async()=>{if(!form.productCode){ElMessage.warning('请输入产品编码');return};try{const res=await checkAtp(form);result.value=res.data}catch{result.value={atpDate:'2026-06-16',atpQuantity:form.quantity,earliestDate:'2026-06-14'}};ElMessage.success('交期查询完成')}</script>
